function logo(name,large=false){const domain=logoDomains[name];if(!domain)return `<span class="fund-initial ${large?'large':''}" aria-hidden="true">${esc(initials(name))}</span>`;return `<span class="fund-logo ${large?'large':''}"><img src="https://www.google.com/s2/favicons?domain=${encodeURIComponent(domain)}&sz=128" alt="" loading="lazy"><span class="fund-initial ${large?'large':''}" aria-hidden="true">${esc(initials(name))}</span></span>`}

async function json(url,optional=false){try{const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error(`${r.status} ${url}`);return r.json()}catch(e){if(optional){console.warn(e);return null}throw e}}
async function supa(path){const r=await fetch(`${SUPABASE_URL}/rest/v1/${path}`,{headers:{apikey:SUPABASE_KEY,Accept:'application/json'}});if(!r.ok)throw new Error(`Supabase ${r.status}`);return r.json()}

async function loadRich(){try{const rows=await supa('api_option_dataset?select=id,fund,option,issuer_growth_pct,latest_data_date');return rows.map(x=>({id:String(x.id),fund:x.fund,option:x.option,issuerGrowth:asNumber(x.issuer_growth_pct),latestDataDate:x.latest_data_date}))}catch(e){console.warn('issuer layer unavailable',e);return[]}}
async function boot(){const [funds,stats,index,cppp,rich]=await Promise.all([json(DATA.funds),json(DATA.stats,true),json(DATA.metricIndex,true),json(DATA.cppp,true),loadRich()]);db.fundIndex=funds;db.stats=stats||{};db.index=index?.options||index||[];db.cppp=cppp;db.rich=rich;restoreWorkspace();render();bindGlobal()}
function restoreWorkspace(){if(workspace.lastFund)state.fund=workspace.lastFund;if(workspace.compareA)state.compareA=workspace.compareA;if(workspace.compareB)state.compareB=workspace.compareB}

async function ensureFund(name){if(db.fundCache.has(name))return db.fundCache.get(name);const meta=slugMeta(name);if(!meta)return null;const [structure,metrics]=await Promise.all([json(`${DATA.fundBase}${meta.slug}.json`,true),json(`${DATA.metricsBase}${meta.slug}.json`,true)]);const payload={meta,structure,metrics};db.fundCache.set(name,payload);return payload}
async function openFund(name){state.view='loading';render();await ensureFund(name);state.fund=name;saveWorkspace({lastFund:name});state.view='fund';render();scrollToTop()}
async function openOption(name,id){state.view='loading';render();const payload=await ensureFund(name);const opt=payload?.structure?.options?.find(o=>String(o.option_id)===String(id));state.fund=name;state.optionId=String(id);rememberViewedOption({fund:name,optionId:id,optionName:opt?.option_name||id});workspace=loadWorkspace();state.view='option';render();scrollToTop()}
function go(view){state.view=view;render();scrollToTop()}
function scrollToTop(){window.scrollTo({top:0,behavior:'smooth'})}

function publicProductIds(structure){return new Set((structure?.products||[]).filter(p=>p.open_to_public&&p.open_to_new_members!==false).map(p=>p.product_id))}
function optionIsPublic(o,structure){const ids=publicProductIds(structure);return (o.pathways||[]).some(p=>ids.has(p.product_id)&&p.menu_open_to_new_members!==false)&&o.open_to_new_members!==false}
function dateMax(rows){return [...(rows||[])].sort((a,b)=>String(b.reporting_period||'').localeCompare(String(a.reporting_period||'')))[0]||null}
function metricSets(name,id){const m=db.fundCache.get(name)?.metrics;return{performance:(m?.performance||[]).filter(x=>String(x.option_id)===String(id)),strategy:(m?.strategy||[]).filter(x=>String(x.option_id)===String(id))}}
function pickStrategy(rows){const acc=(rows||[]).filter(x=>x.phase==='accumulation');return dateMax(acc.length?acc:rows)}
function pickPerformance(rows,balance=100000){const acc=(rows||[]).filter(x=>x.phase==='accumulation');const pool=acc.length?acc:rows;const exact=pool.filter(x=>Number(x.representative_balance)===Number(balance));return dateMax(exact.length?exact:pool)}
function richMatch(fund,optionName){const norm=s=>String(s||'').toLowerCase().replace(/\b(accum|accumulation|super savings|future saver|retirement|choice|ttr)\b/g,'').replace(/[^a-z0-9]+/g,' ').trim();const t=norm(optionName);return db.rich.find(x=>x.fund===fund&&(norm(x.option)===t||norm(x.option).includes(t)||t.includes(norm(x.option))))||null}
const normaliseName=s=>String(s||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
function cpppMatches(fund,optionName){const target=normaliseName(optionName);if(!target)return[];return (db.cppp?.records||[]).filter(x=>x.fund===fund&&normaliseName(x.option_name)===target)}
function optionSummary(name,o,balance=workspace.preferredBalance||100000){const sets=metricSets(name,o.option_id),strategy=pickStrategy(sets.strategy),performance=pickPerformance(sets.performance,balance),rich=richMatch(name,o.option_name);return{strategy,performance,rich}}
function currentIndex(name,id){return db.index.find(x=>x.fund===name&&String(x.option_id)===String(id))||null}
function evidenceFor(name,o){const m=optionSummary(name,o);return evidenceCompleteness({structure:true,performance:!!m.performance,strategy:!!m.strategy,issuer:!!m.rich,history:false})}

function marketStats(){const s=db.stats||{},cppp=db.cppp?.stats||{};return{funds:s.fund_entities??db.fundIndex?.fund_count,publicFunds:s.fund_entities_with_public_products??fundList().filter(x=>x.open_public_products).length,options:s.unique_option_records??db.fundIndex?.unique_options_total,pathways:s.investment_pathways??db.fundIndex?.pathways,performance:s.options_with_performance_metrics,index:s.comparison_index_options??db.index.length,tenYear:s.index_10y_return_count,cpppRecords:cppp.normalised_records??db.cppp?.records?.length??null}}
function growthRangeText(){const min=asNumber(db.stats?.growth_exposure_min_pct),max=asNumber(db.stats?.growth_exposure_max_pct);if(min===null||max===null)return'full growth spectrum';return max>100?`${pct(min,0)} to 100%+`:`${pct(min,0)} to ${pct(max,0)}`}

function home(){const s=marketStats();return `<div>
<section class="hero"><div class="shell hero-grid"><div class="hero-copy"><span class="eyebrow">Australia’s super market, mapped</span><h1>Know what your super is <em>actually doing.</em></h1><p>Find your fund. Find the investment option you actually hold. Then understand its portfolio, long-term performance, fees and risk in plain English — with the receipt behind every number.</p><div class="hero-buttons"><button class="primary" data-view="navigator">Answer my super question</button><button class="secondary" data-view="funds">Explore all funds</button></div><div class="hero-search"><input id="homeSearch" placeholder="Search a super fund" autocomplete="off"><button id="homeSearchGo">Search</button><div id="homeResults" class="search-results" hidden></div></div></div><aside class="market-proof"><span class="proof-label">LIVE MARKET MAP</span><div class="proof-big"><strong>${compact(s.funds)}</strong><span>APRA fund entities</span></div><div class="proof-grid"><div><strong>${compact(s.options)}</strong><span>option records</span></div><div><strong>${compact(s.index)}</strong><span>comparison-ready records</span></div><div><strong>${growthRangeText()}</strong><span>growth exposure represented</span></div><div><strong>${compact(s.pathways)}</strong><span>underlying pathways</span></div></div><p>Coverage is separated from evidence depth. A mapped option is not automatically labelled fully verified.</p></aside></div></section>
<section class="logo-band"><div class="shell"><p>Explore familiar funds</p><div class="logo-row">${featuredFunds().map(f=>`<button data-open-fund="${esc(f.name)}">${logo(f.name)}<span>${esc(displayFundName(f.name))}</span></button>`).join('')}</div></div></section>
<section class="section"><div class="shell"><div class="section-head"><div><span class="eyebrow">Start with what you want answered</span><h2>You don’t need to know the jargon first.</h2></div><p>Choose the question. Super Evidence will show only the evidence needed to answer it, then let you drill deeper if you want.</p></div><div class="question-grid">${questionCards()}</div></div></section>
<section class="section warm"><div class="shell split"><div><span class="eyebrow">Why it is different</span><h2>Broad enough for the whole market. Careful enough to say “we don’t know”.</h2><p class="large-copy">Super Evidence separates market coverage, APRA comparison data, issuer verification and calculated analysis. That keeps missing or differently defined numbers visible instead of smoothing them away.</p></div><div class="evidence-stack"><div><i class="dot structure"></i><span><strong>Market mapped</strong><small>Fund → product → menu → option → pathway.</small></span></div><div><i class="dot apra"></i><span><strong>APRA comparable</strong><small>Performance, strategy, fees and risk where APRA reports them.</small></span></div><div><i class="dot issuer"></i><span><strong>Issuer verified</strong><small>Matched to the fund’s own current or archived disclosure.</small></span></div><div><i class="dot calc"></i><span><strong>Calculated transparently</strong><small>Peer medians and models retain formulas and assumptions.</small></span></div></div></div></section>
<section class="section"><div class="shell"><div class="section-head"><div><span class="eyebrow">A system, not a leaderboard</span><h2>Four steps from confusion to an evidence-backed view.</h2></div></div><div class="steps"><div><span>01</span><strong>Find the fund</strong><p>Start with the organisation you recognise.</p></div><div><span>02</span><strong>Find the actual option</strong><p>This is what determines how your money is invested.</p></div><div><span>03</span><strong>Compare true peers</strong><p>Match growth band, phase and return basis first.</p></div><div><span>04</span><strong>Open the receipt</strong><p>See the source, reporting date and methodology.</p></div></div></div></section>
<section class="section dark"><div class="shell calculator-tease"><div><span class="eyebrow">Transparent calculators</span><h2>See what the assumptions do.</h2><p>Investment return, fees, contributions and inflation are shown separately. Change them yourself.</p><button class="light-button" data-view="calculators">Explore calculators</button></div><div class="tease-result"><span>Illustrative only</span><strong>${money(projectSuper({startingBalance:100000,annualContribution:12000,years:20,returnBeforeInvestmentFeesPct:7,investmentFeePct:.5,annualAdminFee:100,inflationPct:2.5}).endingBalanceTodayDollars)}</strong><small>today’s dollars after 20 years under the displayed example assumptions</small></div></div></section>
</div>`}

function featuredFunds(){const preferred=['AustralianSuper','Australian Retirement Trust','HOSTPLUS Superannuation Fund','UniSuper','Aware Super','Retail Employees Superannuation Trust','HESTA','CONSTRUCTION AND BUILDING UNIONS SUPERANNUATION FUND'];return preferred.map(name=>fundList().find(f=>f.name===name)).filter(Boolean)}
function displayFundName(name){return ({'HOSTPLUS Superannuation Fund':'Hostplus','Retail Employees Superannuation Trust':'Rest','CONSTRUCTION AND BUILDING UNIONS SUPERANNUATION FUND':'Cbus'})[name]||name}
function questionCards(){const rows=[['risk','How much risk am I really taking?','Separate growth exposure, volatility and risk labels.','↗'],['performance','Has my option performed well?','Put long-term return beside genuinely similar options.','↟'],['fees','Am I paying too much?','Compare the same balance and pathway basis.','$'],['holdings','What is my money invested in?','Turn the asset allocation into a readable portfolio.','◫'],['age','What does my time horizon change?','Understand time without turning age into a black-box recommendation.','⌛'],['compare','How does my option compare?','Compare two portfolios without pretending different risks are equal.','↔']];return rows.map(([k,t,p,i])=>`<button class="question-card" data-intent="${k}"><span>${i}</span><strong>${t}</strong><p>${p}</p><small>Explore →</small></button>`).join('')}

function fundSearchResults(q){const term=q.trim().toLowerCase();if(!term)return'';const rows=fundList().filter(f=>f.name.toLowerCase().includes(term)).slice(0,12);return rows.map(f=>`<button class="search-result" data-open-fund="${esc(f.name)}">${logo(f.name)}<span><strong>${esc(displayFundName(f.name))}</strong><small>${compact(f.unique_options_total)} option records${f.open_public_products?` · ${f.open_public_products} public products`:''}</small></span><b>View →</b></button>`).join('')||'<div class="empty">No fund entity matches this search.</div>'}
function fundsPage(){const publicFunds=fundList().filter(f=>f.open_public_products);return `<div class="page"><div class="page-head"><span class="eyebrow">Explore funds</span><h1>Start with the fund you know.</h1><p>Public-offer funds are shown first. APRA also contains employer, restricted and platform structures, which remain available under “all APRA entities”.</p></div><div class="market-summary"><strong>${publicFunds.length}</strong><span>APRA fund entities with public products in the current market structure</span></div><div class="filter-bar"><input id="fundFilter" placeholder="Search funds"><label><input id="showAllFunds" type="checkbox"> Show restricted / other APRA entities</label></div><div id="fundDirectory" class="fund-directory">${fundRows(publicFunds)}</div></div>`}
function fundRows(rows){return rows.map(f=>`<button class="fund-row" data-open-fund="${esc(f.name)}">${logo(f.name)}<span><strong>${esc(displayFundName(f.name))}</strong><small>${compact(f.unique_options_total)} option records · ${compact(f.pathways)} pathways</small></span><b>${f.open_public_products?'Explore':'APRA entity'} →</b></button>`).join('')}

function category(o){const x=`${o.option_category||''} ${o.option_type||''} ${o.option_name||''}`.toLowerCase();if(o.consumer_group==='direct_asset')return'Direct investments';if(x.includes('lifecycle'))return'Lifecycle';if(x.includes('index'))return'Indexed';if(x.includes('social')||x.includes('responsible')||x.includes('ethical')||x.includes('sustainable'))return'Responsible / screened';if(x.includes('single')||x.includes('sector'))return'Specialist / single asset';return'Diversified / managed'}
function fundPage(name){const payload=db.fundCache.get(name),meta=payload?.meta,structure=payload?.structure,metrics=payload?.metrics;if(!structure)return `<div class="page"><div class="empty">The market structure for this fund could not be loaded.</div></div>`;const publicOpts=(structure.options||[]).filter(o=>o.consumer_group==='managed_option'&&optionIsPublic(o,structure));const allOpts=structure.options||[];const perfIds=new Set((metrics?.performance||[]).map(x=>String(x.option_id)));const stratIds=new Set((metrics?.strategy||[]).map(x=>String(x.option_id)));const issuer=db.rich.filter(x=>x.fund===name).length;const coverage=evidenceCompleteness({structure:true,performance:perfIds.size>0,strategy:stratIds.size>0,issuer:issuer>0,history:false});return `<div class="page"><div class="breadcrumbs"><button data-view="funds">Funds</button><span>›</span>${esc(displayFundName(name))}</div><section class="fund-hero"><div class="fund-brand">${logo(name,true)}</div><div><span class="eyebrow">Super fund</span><h1>${esc(displayFundName(name))}</h1><p>${meta?.open_public_products?`${meta.open_public_products} product${meta.open_public_products===1?'':'s'} are reported open to the public in the current APRA structure.`:'This APRA entity does not currently report an open public product in the loaded structure.'} Start with the investment menu rather than trying to interpret every pathway.</p><div class="coverage-chip ${coverage.level}">${esc(coverage.label)}</div></div></section><div class="fund-facts"><div><strong>${compact(meta?.products)}</strong><span>products</span></div><div><strong>${compact(publicOpts.length)}</strong><span>public managed options</span></div><div><strong>${compact(perfIds.size)}</strong><span>with APRA performance</span></div><div><strong>${compact(stratIds.size)}</strong><span>with APRA strategy</span></div></div><section class="fund-options"><div class="section-head"><div><span class="eyebrow">Investment options</span><h2>Find the option you actually hold.</h2></div><p>Search is primary because some platform-style funds contain hundreds or thousands of reported choices.</p></div><input id="fundOptionSearch" class="wide-search" placeholder="Search options in ${esc(displayFundName(name))}"><div id="fundOptions">${groupedOptionPreview(name,publicOpts.length?publicOpts:allOpts)}</div></section><details class="research-detail"><summary>Research detail & APRA structure</summary><div class="research-grid"><div><strong>${compact(meta?.unique_options_total)}</strong><span>unique option records</span></div><div><strong>${compact(meta?.pathways)}</strong><span>pathways</span></div><div><strong>${issuer}</strong><span>issuer-deep options currently loaded</span></div><div><strong>${esc(coverage.label)}</strong><span>evidence state</span></div></div></details></div>`}
function groupedOptionPreview(name,options){const groups=new Map();for(const o of options){const k=category(o);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(o)}const order=['Diversified / managed','Indexed','Lifecycle','Responsible / screened','Specialist / single asset','Direct investments'];return order.filter(k=>groups.has(k)).map(k=>`<div class="option-group"><div class="option-group-title"><strong>${k}</strong><span>${groups.get(k).length} options</span></div>${optionRows(name,groups.get(k).slice(0,20))}${groups.get(k).length>20?`<p class="more-note">Search above to find the remaining ${groups.get(k).length-20} options.</p>`:''}</div>`).join('')||'<div class="empty">No options found.</div>'}
function optionRows(name,rows){return rows.map(o=>{const m=optionSummary(name,o),g=asNumber(m.strategy?.growth_weight_pct)??asNumber(m.rich?.issuerGrowth),p=asNumber(m.performance?.investment_return_10y_pct),fee=asNumber(m.performance?.total_fees_costs_pct);return `<button class="option-row" data-open-option="${esc(o.option_id)}" data-fund="${esc(name)}"><span><strong>${esc(o.option_name||o.option_id)}</strong><small>${esc(o.option_category||o.option_type||category(o))}</small></span><span><small>Growth</small><strong>${g===null?'—':pct(g,0)}</strong></span><span><small>10y return</small><strong>${p===null?'—':pct(p,2)}</strong></span><span><small>Fees*</small><strong>${fee===null?'—':pct(fee,2)}</strong></span><b>View →</b></button>`}).join('')}

function canonicalAsset(label=''){const x=label.toLowerCase();if(x.includes('australian')&&x.includes('equity'))return'Australian shares';if(x.includes('international')&&x.includes('equity'))return'International shares';if(x.includes('equity'))return'Other shares';if(x.includes('property'))return'Property';if(x.includes('infrastructure'))return'Infrastructure';if(x.includes('credit'))return'Credit';if(x.includes('fixed income'))return'Fixed income';if(x.includes('cash'))return'Cash';if(x.includes('alternative'))return'Alternatives';return'Other'}
function broadAllocations(strategy){const map=new Map();for(const a of strategy?.allocations||[]){const v=asNumber(a.benchmark_pct);if(v===null||v===0)continue;const k=canonicalAsset(a.asset_class);map.set(k,(map.get(k)||0)+v)}return [...map.entries()].sort((a,b)=>b[1]-a[1])}
function optionPage(name,id){const payload=db.fundCache.get(name),o=payload?.structure?.options?.find(x=>String(x.option_id)===String(id));if(!o)return fundPage(name);const m=optionSummary(name,o),s=m.strategy,p=m.performance,idx=currentIndex(name,id);const peer=idx?peerContext(idx,db.index):null;const growth=asNumber(s?.growth_weight_pct)??asNumber(m.rich?.issuerGrowth),growthInfo=growthDescriptor(growth,s?.growth_band);const risk=riskPicture({growthPct:growth,growthBand:s?.growth_band,volatility10yPct:p?.volatility_10y_pct,riskLabel:s?.risk_label,negativeReturns20y:s?.negative_return_expectation_20yr});const evidence=evidenceCompleteness({structure:true,performance:!!p,strategy:!!s,issuer:!!m.rich,history:false});const alloc=broadAllocations(s),feePct=asNumber(p?.total_fees_costs_pct),feeDollars=feePct===null?null:(workspace.preferredBalance||100000)*feePct/100;const saved=isSaved(name,id);const three=threeThings(o,m,idx,peer,growthInfo,feeDollars);const freshness=dataFreshness(p?.reporting_period||s?.reporting_period);return `<div class="page option-page"><div class="breadcrumbs"><button data-open-fund="${esc(name)}">${esc(displayFundName(name))}</button><span>›</span>${esc(o.option_name||id)}</div><section class="option-hero"><div><span class="eyebrow">Investment option</span><h1>${esc(o.option_name||id)}</h1><p>${esc(displayFundName(name))} · ${esc(o.option_category||o.option_type||category(o))}</p></div><button class="save-button ${saved?'saved':''}" data-save-option="${esc(id)}" data-fund="${esc(name)}">${saved?'Saved':'Save for later'}</button></section><section class="three-things"><div class="section-head compact"><div><span class="eyebrow">In plain English</span><h2>Three things to know.</h2></div></div><div class="takeaway-grid">${three.map(x=>`<article class="takeaway"><span>${esc(x.kicker)}</span><strong>${esc(x.title)}</strong><p>${esc(x.text)}</p></article>`).join('')}</div></section><section class="signal-strip"><div><span>Growth exposure</span><strong>${growth===null?'—':pct(growth,1)}</strong><small>${esc(s?.growth_band||growthInfo.label)}</small></div><div><span>10-year return</span><strong>${asNumber(p?.investment_return_10y_pct)===null?'—':pct(p.investment_return_10y_pct,2)}</strong><small>${peer?.return10y?`${peer.return10y.difference>=0?'Above':'Below'} matched peer median`:'APRA reported basis'}</small></div><div><span>10-year volatility</span><strong>${asNumber(p?.volatility_10y_pct)===null?'—':pct(p.volatility_10y_pct,2)}</strong><small>Historical variability</small></div><div><span>Estimated fees*</span><strong>${feeDollars===null?'—':money(feeDollars)}</strong><small>at ${money(workspace.preferredBalance||100000)} representative balance</small></div></section><section class="visual-section"><div class="visual-copy"><span class="eyebrow">Risk picture</span><h2>${esc(growthInfo.label)}</h2><p>${esc(risk.explanation)}</p><p class="fine">${esc(risk.warning)}</p></div><div class="growth-meter"><div class="meter-scale"><span>More defensive</span><span>More growth</span></div><div class="meter-track"><div class="meter-fill" style="width:${Math.min(100,Math.max(0,growth||0))}%"></div><i style="left:${Math.min(100,Math.max(0,growth||0))}%"></i></div><strong>${growth===null?'Not available':growth>100?`${pct(growth,1)} leveraged growth exposure`:pct(growth,1)}</strong></div></section><section class="visual-section reverse"><div class="allocation-panel">${allocationVisual(alloc)}</div><div class="visual-copy"><span class="eyebrow">Portfolio</span><h2>What is the money invested in?</h2><p>We group APRA’s detailed strategic categories into plain-English asset classes here. The exact listed/unlisted and hedged/unhedged fields remain available in research detail.</p></div></section><section class="visual-section"><div class="visual-copy"><span class="eyebrow">Long-term performance</span><h2>Put the return in context.</h2><p>${peer?.return10y?`The loaded 10-year return is ${Math.abs(peer.return10y.difference).toFixed(2)} percentage points p.a. ${peer.return10y.difference>=0?'above':'below'} the median across ${peer.peerCount} matched peers using the same phase, APRA growth band and return basis.`:'Matched peer context is not available for this option yet.'}</p><p class="fine">Past performance is not a reliable indicator of future performance.</p></div>${performanceVisual(p)}</section><section class="visual-section reverse"><div class="fee-panel"><span>At a ${money(workspace.preferredBalance||100000)} representative balance</span><strong>${feeDollars===null?'—':money(feeDollars)}</strong><small>${feePct===null?'Matched APRA fee data unavailable':`${pct(feePct,2)} of representative balance`}</small><label>Change working balance<input id="optionBalance" type="number" min="0" step="1000" value="${workspace.preferredBalance||100000}"></label></div><div class="visual-copy"><span class="eyebrow">Fees</span><h2>Show dollars first.</h2><p>Fees depend on balance, product and pathway. The displayed value uses the closest matched APRA representative-balance data rather than attaching one universal fee to an option.</p></div></section><section class="evidence-section"><div><span class="eyebrow">Evidence</span><h2>${esc(evidence.label)}</h2><p>${esc(freshness.label)}${freshness.months!==null?` · about ${freshness.months} months from the reporting date`:''}.</p></div><div class="evidence-pills">${evidence.present.map(x=>`<span>${esc(x.label)}</span>`).join('')}${evidence.missing.map(x=>`<span class="missing">${esc(x.label)} not yet loaded</span>`).join('')}</div></section><details class="research-detail"><summary>Research detail, methodology & original fields</summary><div class="research-body">${researchDetail(name,o,m,idx)}</div></details><div class="option-actions"><button class="primary" data-compare-current="${esc(id)}" data-fund="${esc(name)}">Compare with another option</button><button class="secondary" data-navigator-current="${esc(id)}" data-fund="${esc(name)}">Ask a question about this option</button></div><p class="fine">* Representative fees are pathway- and balance-dependent. No missing fee is inferred.</p></div>`}
function threeThings(o,m,idx,peer,growthInfo,feeDollars){const out=[{kicker:'Risk & growth',title:growthInfo.label,text:growthInfo.plain}];const r=asNumber(m.performance?.investment_return_10y_pct);if(r!==null)out.push({kicker:'Long-term return',title:peer?.return10y?(peer.return10y.difference>=0?'Above the matched peer median':'Below the matched peer median'):`${pct(r,2)} p.a. over 10 years`,text:peer?.return10y?`${pct(r,2)} p.a. versus a ${pct(peer.return10y.median,2)} matched peer median. This is context, not a verdict on investment skill.`:'The 10-year figure is available, but matched peer context is not yet loaded.'});else out.push({kicker:'Long-term return',title:'10-year data not available',text:'We do not substitute a shorter period or a secondary figure without labelling it.'});if(feeDollars!==null)out.push({kicker:'Fees',title:`About ${money(feeDollars)} at the working balance`,text:'Use the balance control below because member outcomes can change as fixed and asset-based fees interact.'});else out.push({kicker:'Evidence',title:'Fee context not yet available',text:'The option remains searchable even when a matched representative fee is missing.'});return out.slice(0,3)}
function allocationVisual(rows){if(!rows.length)return'<div class="empty">Strategic allocation is not available for this option.</div>';const colours=['#c87155','#657d6b','#d9af5f','#6e91a0','#907ba0','#b68c77','#6f7b86','#b9aa95','#8fa48d'];return `<div class="alloc-stack">${rows.map(([k,v],i)=>`<span style="width:${v}%;background:${colours[i%colours.length]}" title="${esc(k)} ${pct(v,1)}"></span>`).join('')}</div><div class="alloc-legend">${rows.map(([k,v],i)=>`<div><i style="background:${colours[i%colours.length]}"></i><span>${esc(k)}</span><strong>${pct(v,1)}</strong></div>`).join('')}</div>`}
function performanceVisual(p){if(!p)return'<div class="empty">Performance history is not available on the loaded APRA basis.</div>';const rows=[['1y',p.investment_return_1y_pct],['3y',p.investment_return_3y_pct],['5y',p.investment_return_5y_pct],['10y',p.investment_return_10y_pct]].filter(([,v])=>asNumber(v)!==null);const max=Math.max(1,...rows.map(([,v])=>Math.abs(asNumber(v))));return `<div class="bar-chart">${rows.map(([lab,v])=>`<div><span>${lab}</span><div><i style="width:${Math.max(2,Math.abs(v)/max*100)}%"></i></div><strong>${pct(v,2)}</strong></div>`).join('')}</div>`}
function cpppRange(rows,key,formatter=pct){const values=[...new Set(rows.map(x=>asNumber(x[key])).filter(x=>x!==null))].sort((a,b)=>a-b);if(!values.length)return'—';return values.length===1?formatter(values[0]):`${formatter(values[0])}–${formatter(values.at(-1))}`}
function cpppOverlay(name,o){const rows=cpppMatches(name,o.option_name);if(!rows.length)return'<div class="cppp-empty"><strong>2026 APRA comparison overlay</strong><p>No exact fund-and-option-name match was found. Super Evidence does not force a fuzzy match.</p></div>';const statuses=[...new Set(rows.map(x=>x.pass_fail_indicator).filter(Boolean))];const source=rows[0]?.source_url;const tested=statuses.length?statuses.join(' / '):'Not reported';const pathwayCount=new Set(rows.map(x=>x.pathway_id).filter(Boolean)).size;return `<section class="cppp-section"><div class="cppp-head"><div><span class="eyebrow">APRA 2026 comparison overlay</span><h3>The latest standardised lens</h3><p>Separate from quarterly APRA metrics and issuer disclosures. ${rows.length} exact-name record${rows.length===1?'':'s'}${pathwayCount?` across ${pathwayCount} pathway${pathwayCount===1?'':'s'}`:''}.</p></div><div class="test-status ${statuses.includes('Fail')?'fail':statuses.includes('Pass')?'pass':'unknown'}"><span>Performance test</span><strong>${esc(tested)}</strong><small>Not a complete quality or suitability assessment</small></div></div><div class="cppp-metrics"><div><span>Strategic growth</span><strong>${cpppRange(rows,'growth_weight_pct')}</strong></div><div><span>10-year investment return</span><strong>${cpppRange(rows,'return_10y_pct',v=>`${pct(v,2)} p.a.`)}</strong></div><div><span>vs SAA benchmark</span><strong>${cpppRange(rows,'return_vs_saa_10y_pct',v=>`${pct(v,2)} p.a.`)}</strong></div><div><span>Total fee at $100k</span><strong>${cpppRange(rows,'total_fee_100k_pct')}</strong></div></div><div class="cppp-table"><div><span>Return period</span><b>3 years</b><b>5 years</b><b>7 years</b><b>10 years</b></div><div><span>Investment return p.a.</span><b>${cpppRange(rows,'return_3y_pct')}</b><b>${cpppRange(rows,'return_5y_pct')}</b><b>${cpppRange(rows,'return_7y_pct')}</b><b>${cpppRange(rows,'return_10y_pct')}</b></div><div><span>Relative to SAA p.a.</span><b>${cpppRange(rows,'return_vs_saa_3y_pct')}</b><b>${cpppRange(rows,'return_vs_saa_5y_pct')}</b><b>${cpppRange(rows,'return_vs_saa_7y_pct')}</b><b>${cpppRange(rows,'return_vs_saa_10y_pct')}</b></div></div><div class="fee-ladder">${[['$10k','total_fee_10k_pct'],['$25k','total_fee_25k_pct'],['$50k','total_fee_50k_pct'],['$100k','total_fee_100k_pct'],['$250k','total_fee_250k_pct']].map(([lab,key])=>`<div><span>${lab}</span><strong>${cpppRange(rows,key)}</strong></div>`).join('')}</div><p class="fine">Released ${esc(db.cppp?.release_date||'28 August 2026')}. Ranges retain pathway differences. ${source?`<a href="${esc(source)}" target="_blank" rel="noopener">APRA source CSV</a>.`:''}</p></section>`}
function researchDetail(name,o,m,idx){return `${cpppOverlay(name,o)}<div class="research-grid"><div><span>Fund</span><strong>${esc(name)}</strong></div><div><span>Option ID</span><strong>${esc(o.option_id)}</strong></div><div><span>Growth band</span><strong>${esc(m.strategy?.growth_band||'—')}</strong></div><div><span>Return basis</span><strong>${esc(idx?.performance_basis||m.performance?.investment_return_basis||'—')}</strong></div><div><span>Reporting date</span><strong>${esc(m.performance?.reporting_period||m.strategy?.reporting_period||'—')}</strong></div><div><span>Evidence layer</span><strong>${esc(evidenceFor(name,o).label)}</strong></div></div><p>Super Evidence preserves the underlying APRA option/pathway identity and keeps issuer verification separate from regulator data. See the public <a href="../methodology.html">methodology</a> for definitions and comparison rules.</p>`}

function navigator(){const x=state.nav;return `<div class="page navigator"><div class="page-head"><span class="eyebrow">Research navigator</span><h1>Start with the question, not the jargon.</h1><p>Build a factual research brief about your current option. This does not turn age or personal circumstances into an automatic product recommendation.</p></div><div class="progress">${[1,2,3,4,5].map(i=>`<i class="${i<=x.step?'active':''}"></i>`).join('')}</div>${wizardStep()}</div>`}
const intents={risk:'How much risk am I really taking?',performance:'Has my option performed well?',fees:'Am I paying too much?',holdings:'What am I invested in?',age:'What does my time horizon change?',compare:'How does my option compare?'};
function wizardStep(){const x=state.nav;if(x.step===1)return `<div class="wizard"><h2>What do you want answered first?</h2><div class="wizard-choices">${Object.entries(intents).map(([k,t])=>`<button data-wizard-intent="${k}"><strong>${esc(t)}</strong><span>${esc(questionCardsText(k))}</span></button>`).join('')}</div></div>`;if(x.step===2)return `<div class="wizard"><h2>What time horizon are you using?</h2><p>We use this only to explain the time until your chosen planning age.</p><div class="form-pair"><label>Your age<input id="wizardAge" type="number" min="18" max="90" value="${x.age}"></label><label>Retirement planning age<input id="wizardRetirementAge" type="number" min="50" max="95" value="${x.retirementAge}"></label></div><div class="wizard-actions"><button class="ghost" data-wizard-back>Back</button><button class="primary" data-wizard-time>Continue</button></div></div>`;if(x.step===3)return `<div class="wizard"><h2>Which fund are you with?</h2><select id="wizardFund"><option value="">Choose a public-offer fund…</option>${fundList().filter(f=>f.open_public_products).map(f=>`<option value="${esc(f.name)}" ${x.fund===f.name?'selected':''}>${esc(displayFundName(f.name))}</option>`).join('')}</select><div class="wizard-actions"><button class="ghost" data-wizard-back>Back</button><button class="primary" data-wizard-fund ${x.fund?'':'disabled'}>Continue</button></div></div>`;if(x.step===4){const p=x.fund?db.fundCache.get(x.fund):null,opts=(p?.structure?.options||[]).filter(o=>o.consumer_group==='managed_option'&&optionIsPublic(o,p?.structure)).sort((a,b)=>(asNumber(b.member_assets)||0)-(asNumber(a.member_assets)||0));return `<div class="wizard"><h2>Which investment option are you actually in?</h2><p>The option is what determines the portfolio. Search the name shown in your fund account.</p><input id="wizardOptionSearch" class="wide-search" placeholder="Balanced, High Growth, Lifecycle…"><div id="wizardOptionResults" class="wizard-results">${wizardOptionRows(opts.slice(0,20))}</div><div class="wizard-actions"><button class="ghost" data-wizard-back>Back</button><button class="secondary" data-wizard-unknown>I don’t know my option</button></div></div>`}return briefPage()}
function questionCardsText(k){return ({risk:'Separate growth exposure, volatility and other risk measures.',performance:'Compare long-term returns only with a matched peer set.',fees:'Use the same representative balance and pathway basis.',holdings:'Translate APRA asset classes into a readable portfolio.',age:'Understand time without an automatic recommendation.',compare:'See which differences are truly like-for-like.'})[k]||''}
function wizardOptionRows(rows){return rows.map(o=>`<button class="search-result" data-wizard-option="${esc(o.option_id)}"><span class="fund-initial">IO</span><span><strong>${esc(o.option_name||o.option_id)}</strong><small>${esc(o.option_category||o.option_type||category(o))}</small></span><b>Use →</b></button>`).join('')||'<div class="empty">No public managed option matches this search.</div>'}
function briefPage(){const x=state.nav,p=x.fund?db.fundCache.get(x.fund):null,o=x.optionId?p?.structure?.options?.find(v=>String(v.option_id)===String(x.optionId)):null,subject=o?currentIndex(x.fund,o.option_id):null;const brief=buildResearchBrief({intent:x.intent,age:x.age,retirementAge:x.retirementAge,subject,universe:db.index});return `<div class="brief"><div class="brief-head"><span class="eyebrow">Your research brief</span><h2>${o?esc(o.option_name):x.fund?esc(displayFundName(x.fund)):'Your super question'}</h2><p>${esc(brief.disclaimer)}</p></div><div class="brief-answer-grid">${brief.answers.map(a=>`<article><strong>${esc(a.title)}</strong><p>${esc(a.text)}</p></article>`).join('')}</div><div class="horizon-card"><span>Selected planning horizon</span><strong>${brief.horizon.years===null?'—':`${brief.horizon.years} years`}</strong><p>${esc(brief.horizon.explanation)}</p></div><div class="wizard-actions">${o?`<button class="primary" data-open-option="${esc(o.option_id)}" data-fund="${esc(x.fund)}">Open the evidence</button><button class="secondary" data-compare-current="${esc(o.option_id)}" data-fund="${esc(x.fund)}">Compare peers</button>`:x.fund?`<button class="primary" data-open-fund="${esc(x.fund)}">Explore this fund</button>`:''}<button class="ghost" data-wizard-restart>Start again</button></div></div>`}

function comparePage(){const a=state.compareA,b=state.compareB;return `<div class="page"><div class="page-head"><span class="eyebrow">Compare</span><h1>See what is actually different.</h1><p>Choose two options. The system checks whether the comparison is economically sensible before interpreting headline returns.</p></div><div class="compare-pickers"><div><label>Option A</label><input id="compareAInput" placeholder="Search fund or option" value="${a?esc(`${displayFundName(a.fund)} — ${a.option_name}`):''}"><div id="compareAResults" class="search-results" hidden></div></div><button class="swap" data-swap-compare>↔</button><div><label>Option B</label><input id="compareBInput" placeholder="Search fund or option" value="${b?esc(`${displayFundName(b.fund)} — ${b.option_name}`):''}"><div id="compareBResults" class="search-results" hidden></div></div></div>${a&&b?comparisonResult(a,b):'<div class="empty">Choose two comparison-ready APRA records.</div>'}</div>`}
function compareSearch(q,side){const t=q.trim().toLowerCase();if(t.length<2)return'';return db.index.filter(x=>`${x.fund} ${x.option_name}`.toLowerCase().includes(t)).slice(0,14).map(x=>`<button class="search-result" data-compare-pick="${side}" data-fund="${esc(x.fund)}" data-option-id="${esc(x.option_id)}">${logo(x.fund)}<span><strong>${esc(x.option_name)}</strong><small>${esc(displayFundName(x.fund))} · ${esc(x.growth_band||'growth band unavailable')}</small></span><b>Select</b></button>`).join('')||'<div class="empty">No comparison-ready record found.</div>'}
function comparisonResult(a,b){const analysis=comparisonTakeaways(a,b);return `<section class="comparison-result"><div class="comparison-status ${analysis.fit.level}"><span>${analysis.fit.level==='strong'?'Strong comparison':analysis.fit.level==='usable_with_context'?'Usable with context':'Weak comparison'}</span><strong>${esc(analysis.fit.explanation)}</strong>${analysis.fit.issues.length?`<small>${esc(analysis.fit.issues.join(' · '))}</small>`:''}</div><div class="section-head compact"><div><span class="eyebrow">What stands out</span><h2>Start with the takeaways.</h2></div></div><div class="compare-takeaways">${analysis.takeaways.map(t=>`<div><i></i><p>${esc(t)}</p></div>`).join('')}</div><div class="compare-visuals"><div class="compare-card"><span>Growth exposure</span>${dualBars(a.growth_weight_pct,b.growth_weight_pct,a.option_name,b.option_name,'%')}</div><div class="compare-card"><span>10-year investment return</span>${dualBars(a.return_10y_pct,b.return_10y_pct,a.option_name,b.option_name,'% p.a.')}</div><div class="compare-card"><span>Total fees at $100k</span>${dualBars(a.fee_100k_pct,b.fee_100k_pct,a.option_name,b.option_name,'%')}</div><div class="compare-card"><span>10-year volatility</span>${dualBars(a.volatility_10y_pct,b.volatility_10y_pct,a.option_name,b.option_name,'%')}</div></div><details class="research-detail"><summary>Show exact APRA comparison fields</summary><div class="compare-exact">${[['Fund',a.fund,b.fund],['Option',a.option_name,b.option_name],['Growth band',a.growth_band,b.growth_band],['Phase',a.phase,b.phase],['Return basis',a.performance_basis,b.performance_basis],['10-year return',pct(a.return_10y_pct,2),pct(b.return_10y_pct,2)],['Fee at $100k',pct(a.fee_100k_pct,2),pct(b.fee_100k_pct,2)]].map(r=>`<div><span>${esc(r[0])}</span><strong>${esc(r[1]??'—')}</strong><strong>${esc(r[2]??'—')}</strong></div>`).join('')}</div></details></section>`}
function dualBars(av,bv,an,bn,unit){const a=asNumber(av),b=asNumber(bv),max=Math.max(1,Math.abs(a||0),Math.abs(b||0));return `<div class="dual-bars"><div><small>${esc(an)}</small><div><i style="width:${a===null?0:Math.abs(a)/max*100}%"></i></div><strong>${a===null?'—':`${a.toFixed(2)}${unit}`}</strong></div><div><small>${esc(bn)}</small><div><i style="width:${b===null?0:Math.abs(b)/max*100}%"></i></div><strong>${b===null?'—':`${b.toFixed(2)}${unit}`}</strong></div></div>`}

function calculatorsPage(){const b=workspace.preferredBalance||100000;return `<div class="page"><div class="page-head"><span class="eyebrow">Calculators</span><h1>Every assumption is visible.</h1><p>Start with a projection, then see how fees and inflation change the result. This is illustrative modelling, not a forecast.</p></div><div class="calculator-layout"><div class="calculator-inputs"><h2>Super projection</h2><label>Starting balance<input id="calcBalance" type="number" value="${b}"></label><label>Annual contributions<input id="calcContribution" type="number" value="12000"></label><label>Years<input id="calcYears" type="number" value="25"></label><label>Investment return before investment fee<input id="calcReturn" type="number" step="0.1" value="7"></label><label>Investment fee (% p.a.)<input id="calcInvestmentFee" type="number" step="0.01" value="0.5"></label><label>Annual administration fee<input id="calcAdminFee" type="number" value="100"></label><label>Inflation (% p.a.)<input id="calcInflation" type="number" step="0.1" value="2.5"></label></div><div id="calcResult">${calculatorResult({startingBalance:b,annualContribution:12000,years:25,returnBeforeInvestmentFeesPct:7,investmentFeePct:.5,annualAdminFee:100,inflationPct:2.5})}</div></div></div>`}
function calculatorResult(inputs){const r=projectSuper(inputs);return `<div class="calculator-result"><span>Illustrative balance</span><strong>${money(r.endingBalanceNominal)}</strong><small>future nominal dollars</small><div class="real-result"><span>In today’s dollars</span><strong>${money(r.endingBalanceTodayDollars)}</strong></div><div class="calc-breakdown"><div><span>Contributions added</span><strong>${money(r.totalContributions)}</strong></div><div><span>Approx. investment-fee drag*</span><strong>${money(r.totalInvestmentFeesApprox)}</strong></div><div><span>Administration fees</span><strong>${money(r.totalAdminFees)}</strong></div><div><span>Net return after investment fee</span><strong>${pct(r.netReturnAfterInvestmentFeePct,2)}</strong></div><div><span>Real net return</span><strong>${pct(r.realNetReturnPct,2)}</strong></div></div><details><summary>Assumptions & exclusions</summary><p>${esc(r.assumptions.contributionTiming)}. ${esc(r.assumptions.returnConvention)} ${esc(r.assumptions.adminFeeTiming)} ${esc(r.assumptions.inflation)}</p><p>${esc(r.assumptions.exclusions)}</p></details><p class="fine">* Approximate investment-fee drag is an illustrative decomposition, not an issuer fee quote.</p></div>`}

const LEARN={basics:['The one distinction to understand first','Your super fund is the organisation. Your investment option is the portfolio inside that fund. Two people in the same fund can therefore have very different investments.'],risk:['Growth exposure is not a risk percentage','APRA growth exposure describes the strategic asset mix. Volatility, expected negative returns and other risk characteristics are separate measures.'],returns:['Compare the same kind of return','Net investment return, member net return and other APRA return bases are not interchangeable. Super Evidence checks the basis before interpreting a comparison.'],fees:['Fees depend on balance and pathway','A fee can change with account balance and the product/menu pathway used to access an option. That is why we show the representative balance.'],peers:['What makes a peer a peer?','The default peer set matches product phase, APRA growth band and return basis. That is more defensible than comparing options simply because both are called “Balanced”.'],evidence:['Every number needs a receipt','Market structure, APRA metrics, issuer disclosure and Super Evidence calculations remain separate evidence layers.']};
function learnPage(){const [title,text]=LEARN[state.learn]||LEARN.basics;return `<div class="page"><div class="page-head"><span class="eyebrow">Learn</span><h1>Understand super one useful idea at a time.</h1></div><div class="learn-layout"><nav>${Object.entries(LEARN).map(([k,[t]])=>`<button data-learn="${k}" class="${state.learn===k?'active':''}">${esc(t)}</button>`).join('')}</nav><article><span class="eyebrow">Plain English</span><h2>${esc(title)}</h2><p>${esc(text)}</p><p>When you want the technical definition, open the research detail on a fund or option page rather than learning everything before you start.</p></article></div></div>`}
function workspacePage(){workspace=loadWorkspace();return `<div class="page"><div class="page-head"><span class="eyebrow">My research</span><h1>Your scratchpad. No account required.</h1><p>${esc(workspacePrivacyText())}</p></div><div class="workspace-grid"><section><h2>Saved options</h2>${workspace.saved.length?workspace.saved.map(x=>`<button class="workspace-item" data-open-option="${esc(x.optionId)}" data-fund="${esc(x.fund)}"><strong>${esc(x.optionName)}</strong><span>${esc(displayFundName(x.fund))}</span></button>`).join(''):'<div class="empty">Save options from an option page to keep them here.</div>'}</section><section><h2>Recently viewed</h2>${workspace.recent.length?workspace.recent.map(x=>`<button class="workspace-item" data-open-option="${esc(x.optionId)}" data-fund="${esc(x.fund)}"><strong>${esc(x.optionName)}</strong><span>${esc(displayFundName(x.fund))}</span></button>`).join(''):'<div class="empty">Recently viewed options will appear here.</div>'}</section><section><h2>Working assumptions</h2><label>Preferred balance<input id="workspaceBalance" type="number" value="${workspace.preferredBalance||100000}"></label><p class="fine">Used for fee illustrations where matched data is available.</p></section><section><h2>Privacy</h2><p>${esc(workspacePrivacyText())}</p><button class="secondary" data-clear-workspace>Clear this browser workspace</button></section></div></div>`}
function aboutPage(){return `<div class="page"><div class="page-head"><span class="eyebrow">About</span><h1>The evidence layer for Australian super.</h1><p>Super Evidence is designed around breadth, comparability and source transparency rather than paid rankings.</p></div><div class="steps"><div><span>01</span><strong>APRA backbone</strong><p>The regulated market structure and standardised metrics.</p></div><div><span>02</span><strong>Issuer overlay</strong><p>Current fund disclosures and historical verification.</p></div><div><span>03</span><strong>Economic logic</strong><p>Peer construction and calculations use one shared engine.</p></div><div><span>04</span><strong>Visible uncertainty</strong><p>Missing or conflicting data remains visible.</p></div></div></div>`}
function loading(){return'<div class="boot"><span class="spinner"></span>Loading the evidence layer…</div>'}

function render(){const app=$('#app');if(!app)return;const fn={home, funds:fundsPage, fund:()=>fundPage(state.fund), option:()=>optionPage(state.fund,state.optionId), navigator, compare:comparePage, calculators:calculatorsPage, learn:learnPage, workspace:workspacePage, about:aboutPage, loading}[state.view]||home;app.innerHTML=fn();document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));bindView()}

function bindGlobal(){if(document.body.dataset.bound)return;document.body.dataset.bound='1';document.addEventListener('click',async e=>{const v=e.target.closest('[data-view]');if(v){go(v.dataset.view);return}const f=e.target.closest('[data-open-fund]');if(f){await openFund(f.dataset.openFund);return}const o=e.target.closest('[data-open-option]');if(o){await openOption(o.dataset.fund||state.fund,o.dataset.openOption);return}const intent=e.target.closest('[data-intent]');if(intent){state.nav={...state.nav,step:2,intent:intent.dataset.intent};saveWorkspace({lastIntent:intent.dataset.intent});go('navigator');return}const wi=e.target.closest('[data-wizard-intent]');if(wi){state.nav={...state.nav,intent:wi.dataset.wizardIntent,step:2};render();return}if(e.target.closest('[data-wizard-back]')){state.nav.step=Math.max(1,state.nav.step-1);render();return}if(e.target.closest('[data-wizard-time]')){state.nav.age=asNumber($('#wizardAge')?.value)||30;state.nav.retirementAge=asNumber($('#wizardRetirementAge')?.value)||67;state.nav.step=3;render();return}if(e.target.closest('[data-wizard-fund]')){const name=$('#wizardFund')?.value;if(name){state.view='loading';render();await ensureFund(name);state.nav.fund=name;state.nav.step=4;state.view='navigator';render()}return}const wo=e.target.closest('[data-wizard-option]');if(wo){state.nav.optionId=wo.dataset.wizardOption;state.nav.step=5;render();return}if(e.target.closest('[data-wizard-unknown]')){state.nav.optionId=null;state.nav.step=5;render();return}if(e.target.closest('[data-wizard-restart]')){state.nav={step:1,intent:null,age:30,retirementAge:67,fund:null,optionId:null};render();return}const cmp=e.target.closest('[data-compare-current]');if(cmp){state.compareA=currentIndex(cmp.dataset.fund,cmp.dataset.compareCurrent);state.compareB=null;saveComparison(state.compareA,null);workspace=loadWorkspace();go('compare');return}const nav=e.target.closest('[data-navigator-current]');if(nav){state.nav={...state.nav,step:5,intent:'compare',fund:nav.dataset.fund,optionId:nav.dataset.navigatorCurrent};go('navigator');return}const pick=e.target.closest('[data-compare-pick]');if(pick){const x=db.index.find(v=>v.fund===pick.dataset.fund&&String(v.option_id)===String(pick.dataset.optionId));if(pick.dataset.comparePick==='A')state.compareA=x;else state.compareB=x;saveComparison(state.compareA,state.compareB);workspace=loadWorkspace();render();return}if(e.target.closest('[data-swap-compare]')){[state.compareA,state.compareB]=[state.compareB,state.compareA];saveComparison(state.compareA,state.compareB);render();return}const save=e.target.closest('[data-save-option]');if(save){const p=db.fundCache.get(save.dataset.fund),opt=p?.structure?.options?.find(x=>String(x.option_id)===String(save.dataset.saveOption));toggleSavedOption({fund:save.dataset.fund,optionId:save.dataset.saveOption,optionName:opt?.option_name});workspace=loadWorkspace();render();return}const learn=e.target.closest('[data-learn]');if(learn){state.learn=learn.dataset.learn;render();return}if(e.target.closest('[data-clear-workspace]')){workspace=clearWorkspace();state.compareA=null;state.compareB=null;render();return}});
const dialog=$('#searchDialog'),input=$('#dialogSearchInput');$('#globalSearchButton')?.addEventListener('click',()=>{dialog?.showModal();setTimeout(()=>input?.focus(),30)});$('#closeSearch')?.addEventListener('click',()=>dialog?.close());input?.addEventListener('input',()=>{const out=$('#dialogSearchResults');if(out)out.innerHTML=fundSearchResults(input.value)});dialog?.addEventListener('click',e=>{if(e.target===dialog)dialog.close()})}

function bindView(){if(state.view==='home'){const i=$('#homeSearch'),out=$('#homeResults');const run=()=>{if(!out)return;out.innerHTML=fundSearchResults(i?.value||'');out.hidden=!(i?.value||'').trim()};i?.addEventListener('input',run);$('#homeSearchGo')?.addEventListener('click',run)}if(state.view==='funds'){const filter=$('#fundFilter'),all=$('#showAllFunds');const run=()=>{let rows=all?.checked?fundList():fundList().filter(f=>f.open_public_products);const q=filter?.value.trim().toLowerCase();if(q)rows=rows.filter(f=>f.name.toLowerCase().includes(q));const out=$('#fundDirectory');if(out)out.innerHTML=fundRows(rows)};filter?.addEventListener('input',run);all?.addEventListener('change',run)}if(state.view==='fund'){const i=$('#fundOptionSearch');i?.addEventListener('input',()=>{const p=db.fundCache.get(state.fund),q=i.value.trim().toLowerCase();let rows=(p?.structure?.options||[]).filter(o=>!q||`${o.option_name} ${o.option_category} ${o.option_type}`.toLowerCase().includes(q));if(!q){const pubs=rows.filter(o=>o.consumer_group==='managed_option'&&optionIsPublic(o,p?.structure));if(pubs.length)rows=pubs}const out=$('#fundOptions');if(out)out.innerHTML=q?optionRows(state.fund,rows.slice(0,80)):groupedOptionPreview(state.fund,rows)})}if(state.view==='option'){$('#optionBalance')?.addEventListener('change',e=>{setPreferredBalance(e.target.value);workspace=loadWorkspace();render()})}if(state.view==='navigator'&&state.nav.step===3){const s=$('#wizardFund');s?.addEventListener('change',()=>{state.nav.fund=s.value;const b=document.querySelector('[data-wizard-fund]');if(b)b.disabled=!s.value})}if(state.view==='navigator'&&state.nav.step===4){const i=$('#wizardOptionSearch');i?.addEventListener('input',()=>{const p=db.fundCache.get(state.nav.fund),q=i.value.toLowerCase();const rows=(p?.structure?.options||[]).filter(o=>o.consumer_group==='managed_option'&&optionIsPublic(o,p?.structure)&&String(o.option_name||'').toLowerCase().includes(q)).slice(0,40);const out=$('#wizardOptionResults');if(out)out.innerHTML=wizardOptionRows(rows)})}if(state.view==='compare'){for(const side of ['A','B']){const i=$(`#compare${side}Input`),out=$(`#compare${side}Results`);i?.addEventListener('input',()=>{if(!out)return;out.innerHTML=compareSearch(i.value,side);out.hidden=i.value.trim().length<2})}}if(state.view==='calculators'){const ids=['calcBalance','calcContribution','calcYears','calcReturn','calcInvestmentFee','calcAdminFee','calcInflation'];const run=()=>{const input={startingBalance:$('#calcBalance')?.value,annualContribution:$('#calcContribution')?.value,years:$('#calcYears')?.value,returnBeforeInvestmentFeesPct:$('#calcReturn')?.value,investmentFeePct:$('#calcInvestmentFee')?.value,annualAdminFee:$('#calcAdminFee')?.value,inflationPct:$('#calcInflation')?.value};const out=$('#calcResult');if(out)out.innerHTML=calculatorResult(input)};ids.forEach(id=>$(`#${id}`)?.addEventListener('input',run))}if(state.view==='workspace'){$('#workspaceBalance')?.addEventListener('change',e=>{setPreferredBalance(e.target.value);workspace=loadWorkspace()})}}

boot().catch(e=>{console.error(e);const app=$('#app');if(app)app.innerHTML=`<div class="page"><div class="empty"><strong>Super Evidence could not load the market system.</strong><p>${esc(e.message)}</p></div></div>`});
